package main

import (
	"fmt"
	"iter"
)

type Stack[T any] struct {
	items []T
}

func (s *Stack[T]) Push(v T) {
	s.items = append(s.items, v)
}

func (s *Stack[T]) All() iter.Seq[T] {
	return func(yield func(T) bool) {
		for i := len(s.items) - 1; i >= 0; i-- {
			if !yield(s.items[i]) {
				return
			}
		}
	}
}

func main() {
	var s Stack[string]
	s.Push("lamp")
	s.Push("book")
	s.Push("kite")
	for p := range s.All() {
		fmt.Println(p)
	}
}

