package main

import (
	"fmt"
	"iter"
	"slices"
)

func Filter[T any](seq iter.Seq[T], keep func(T) bool) iter.Seq[T] {
	return func(yield func(T) bool) {
		for v := range seq {
			if keep(v) && !yield(v) {
				return
			}
		}
	}
}

func main() {
	nums := slices.Values([]int{1, 2, 3, 4, 5, 6})
	even := func(n int) bool { return n%2 == 0 }
	fmt.Println(slices.Collect(Filter(nums, even)))
	for v := range Filter(nums, even) {
		if v > 2 {
			fmt.Println("first big:", v)
			break
		}
	}
}

