package main

import (
	"fmt"
	"iter"
)

var reads = 0

func readLine(i int) string {
	reads++
	return fmt.Sprint("line ", i)
}

func AllLines(n int) []string {
	var lines []string
	for i := 1; i <= n; i++ {
		lines = append(lines, readLine(i))
	}
	return lines
}

func Lines(n int) iter.Seq[string] {
	return func(yield func(string) bool) {
		for i := 1; i <= n; i++ {
			if !yield(readLine(i)) {
				return
			}
		}
	}
}

func main() {
	for _, l := range AllLines(1000000) {
		if l == "line 3" {
			break
		}
	}
	fmt.Println("slice: lines read =", reads)
	reads = 0
	for l := range Lines(1000000) {
		if l == "line 3" {
			break
		}
	}
	fmt.Println("iterator: lines read =", reads)
}

