package main

import "fmt"

type Stack[T any] struct {
	items []T
}

func (s *Stack[T]) Push(v T) {
	s.items = append(s.items, v)
}

func (s *Stack[T]) Pop() (T, bool) {
	var zero T
	if len(s.items) == 0 {
		return zero, false
	}
	top := s.items[len(s.items)-1]
	s.items = s.items[:len(s.items)-1]
	return top, true
}

func main() {
	var parcels Stack[string]
	parcels.Push("lamp")
	parcels.Push("book")
	top, ok := parcels.Pop()
	fmt.Println(top, ok)
	parcels.Push("kite")
	fmt.Println(parcels.items)
	var nums Stack[int]
	n, ok := nums.Pop()
	fmt.Println(n, ok)
}

