package main

import "fmt"

type Stack[T any] struct {
	items []T
}

func (s *Stack[T]) Push(v T) {
	s.items = append(s.items, v)
}

func (s *Stack[T]) Pop() (T, bool) {
	var zero T
	if len(s.items) == 0 {
		return zero, false
	}
	top := s.items[len(s.items)-1]
	s.items = s.items[:len(s.items)-1]
	return top, true
}

func main() {
	var s Stack[int]
	for _, n := range []int{5, 8, 0, 3, 0, 0, 0} {
		popped := "-"
		if n == 0 {
			if v, ok := s.Pop(); ok {
				popped = fmt.Sprint(v)
			}
		} else {
			s.Push(n)
		}
		fmt.Println(n, popped, len(s.items))
	}
}
